blocks.code:
.courses {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
}

@media (max-width: 800px) {
  .courses {
    grid-template-columns: repeat(2, 1fr);
  }
}

@media (max-width: 500px) {
  .courses {
    grid-template-columns: 1fr;
  }
}

.dashboard {
  display: grid;
  grid-template-columns: 240px 1fr;
}

.card-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
}

.header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 20px;
}

.nav {
  display: flex;
  gap: 16px;
}

@media (max-width: 650px) {
  .header {
    flex-direction: column;
    align-items: stretch;
  }

  .nav {
    flex-direction: column;
  }
}

.card {
  position: relative;
}

.badge {
  position: absolute;
  top: 12px;
  right: 12px;
}

.header {
  position: relative;
  z-index: 10;
}

.modal {
  position: fixed;
  z-index: 100;
}

.card {
  background: var(--surface);
  border-radius: var(--radius);
  padding: var(--space);
}

button {
  background: var(--primary);
}

.title::after {
  content: "";
  display: block;
  width: 50px;
  height: 3px;
  margin-top: 8px;
  background: var(--primary);
}

.form {
  width: min(90%, 500px);
  margin: 0 auto;
}

.form input,
.form button {
  width: 100%;
  box-sizing: border-box;
}

:root {
  --background: #0A0F1E;
  --surface: #121A2B;
  --text: #E5E7EB;
  --muted: #94A3B8;
  --primary: #38BDF8;
  --radius: 14px;
  --space: 16px;
}

* {
  box-sizing: border-box;
}

body {
  margin: 0;
  background: var(--background);
  color: var(--text);
  font-family: Arial, sans-serif;
}

.app-shell {
  min-height: 100vh;
  display: grid;
  grid-template-columns: 230px 1fr;
}

.sidebar {
  padding: 20px;
  background: var(--surface);
}

.sidebar nav {
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.page {
  min-width: 0;
}

.topbar {
  min-height: 72px;
  padding: 16px 24px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
}

.content {
  width: 92%;
  max-width: 1200px;
  margin: 0 auto;
  padding: 24px 0;
}

.stats {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 16px;
}

.card,
.course-card {
  padding: 20px;
  background: var(--surface);
  border-radius: var(--radius);
}

.courses {
  margin-top: 24px;
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(220px, 1fr));
  gap: 20px;
}

.course-card h2 {
  font-size: clamp(1.2rem, 2vw, 1.6rem);
}

.course-card p {
  color: var(--muted);
  line-height: 1.6;
}

button {
  padding: 12px 16px;
  border: 0;
  border-radius: 10px;
  font-weight: 700;
}

button:focus-visible {
  outline: 2px solid var(--primary);
  outline-offset: 3px;
}

@media (max-width: 800px) {
  .app-shell {
    grid-template-columns: 1fr;
  }

  .sidebar {
    display: none;
  }

  .stats {
    grid-template-columns: 1fr;
  }

  .content {
    width: 94%;
  }
}

@media (min-width: 801px) {
  .sidebar {
    position: sticky;
    top: 0;
    min-height: 100vh;
  }
}

